INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("ねぇねぇ、騎士クン\n手伝ってあげようよ～", 2, 1, 1.4, 0, "お！\nあそこに困ってそうな人発見！", 0, 1001, 1, "春咲 ひより", 0, 0, 0, 1, "ヒヨリでっす♪\n元気いっぱいがんばるよ♪");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("わ、わたし、\nなに言ってるんだろ\nあはは…", 2, 1, 1.4, 0, "大切な人を\n守れるようになりたい…って", 0, 1002, 1, "草野 優衣", 0, 0, 0, 1, "みんなみたいに\nわたしも強くならなきゃ");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("少しは磨かれると思いますよ。", 2, 1, 1.4, 0, "キミに必要な集中力と感性が", 0, 1003, 1, "士条 怜", 0, 0, 0, 1, "フェンシングを始めてみては？");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("みそぎはねぇ、\nかくれんぼやりたい！", 2, 1, 1.5, 0, "今日はなにして遊ぶ？", 0, 1004, 1, "穂高 みそぎ", 0, 0, 0, 1, "ねぇ、にいちゃん！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("私といっしょに…\nいかない？", 2, 1, 1.4, 0, "ねぇ…", 0, 1006, 1, "風宮 あかり", 0, 0, 0, 1, "風宮あかりです");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("食べ物の恨みは怖いのー", 2, 1, 1.5, 0, "プリンたべたいのー", 0, 1007, 1, "出雲 宮子", 0, 0, 0, 1, "出雲宮子なのー");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("いいよ。\n見られることは運命さ…", 2, 1, 1.4, 0, "キミもボクの美貌に\n吸い寄せられたんだね。", 0, 1008, 1, "虹村 雪", 0, 0, 0, 1, "ボクは虹村雪。");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("人呼んで「疾風の冥姫」!!", 2, 1, 1.4, 0, "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", 0, 1009, 1, "柊杏奈", 0, 0, 0, 1, "フッ…聞いて後悔するがいい！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("ほんまおおきにやわ～♪", 2, 1, 1.5, 0, "うさぎさん、\n運命の王子はんに巡りあわせてくれて", 0, 1010, 1, "姫宮 真歩", 0, 0, 0, 1, "マホマホ王国のプリンセス、\nまほ姫どす");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("ここで会ったが\n100年目～！", 2, 1, 1.4, 0, "生き別れたお兄ちゃんを探して\n三千世界！", 0, 1011, 1, "衣之咲 璃乃", 0, 0, 0, 1, "衣之咲璃乃です！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("…って、お願い！\n誰にも言わないでおいて～！", 2, 1, 1.4, 0, "ち、超能力って…\n何のことかな～？", 0, 1012, 1, "柏崎 初音", 0, 0, 0, 1, "私はハツネ、\n結構強いんだよ。\nきらーん☆");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("ヒデサイまぢ\nGF（グッドフィーリング）～♪", 2, 1, 1.4, 0, "一応カリスマ読モJKやってまっす！", 0, 1016, 1, "美波 鈴奈", 0, 0, 0, 1, "ちょす！\n美波鈴奈だよ～♪");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("でも、沖縄もとってもいいとこさー", 2, 1, 1.4, 0, "東京は遊園地みたいなところさー", 0, 1017, 1, "喜屋武 香織", 0, 0, 0, 1, "はいたーい。\n喜屋武香織さー。");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("イオちゃんって呼んでね。", 2, 1, 1.4, 0, "先生って呼ばれるのは\nくすぐったいから", 0, 1018, 1, "支倉 伊緒", 0, 0, 0, 1, "支倉伊緒です。");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("ミミをおいてかないでぇ～", 2, 1, 1.5, 0, "あ！/\お兄ちゃ～ん\nまってよ～", 0, 1020, 1, "茜 ミミ", 0, 0, 0, 1, "ふえ…？\nミミ、むずかしいこと\nよくわかんない…");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("ふぇぇぇぇぇん……", 2, 1, 1.5, 0, "あの……\nふぇ……", 0, 1021, 1, "栗林 くるみ", 0, 0, 0, 1, "あ…あの…えっと…\n栗…林…くるみ…です……");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("なんてありがとうございます！", 2, 1, 1.4, 0, "こんな私に貴重な時間を\n割いていただき、", 0, 1022, 1, "風宮 より", 0, 0, 0, 1, "風宮よりです。\nあああああ！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("私こっち行きたいー\nね、早く早くー", 2, 1, 1.5, 0, "おにいちゃんどこいくの？\nえ？", 0, 1023, 1, "北条 綾音", 0, 0, 0, 1, "私、アヤネ！\nぷうきちと一緒についてってあげるね！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("これて何か違う…\nあああすみません！", 2, 1, 1.4, 0, "ふ、不束者ですが\nどうぞ末永く…って、", 0, 1025, 1, "天野 すずめ", 0, 0, 0, 1, "わっ…わっ…私、\n天野すずめといいます！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("離しませんわ………\n絶対に…!!", 2, 1, 1.4, 0, "あなたは…運命の……\n伴侶……", 0, 1027, 1, "倉石 恵理子", 0, 0, 0, 1, "……クスクス…私は\n…倉石恵理子……");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("…そうでしょ？？", 2, 1, 1.4, 0, "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", 0, 1028, 1, "佐々木 咲恋", 0, 0, 0, 1, "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("あはは、\n私もまだまだだなぁ～", 2, 1, 1.4, 0, "ぇっと…\nキミ、私のこと知らないの?!", 0, 1029, 1, "桜井 望", 0, 0, 0, 1, "桜井望だよ！\nよろしくねっ");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("ショーグン、\nワタシと一緒に天下統一デース！", 2, 1, 1.4, 0, "初めまして、\n私はニノン・ジュベール申すデス！", 0, 1030, 1, "ニノン・ジュベール", 0, 0, 0, 1, "デケデケデンっ！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("おかしいですね……", 2, 1, 1.4, 0, "でもって私の隣にいるのが……\nえ、見えない？", 0, 1031, 1, "上喜 しのぶ", 0, 0, 0, 1, "上喜しのぶです。\n手元のドクロが父です。");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("そう、\nオラのボケに突っ込める相方が…！", 2, 1, 1.5, 0, "けんども\nそれには足りないモンが…", 0, 1033, 1, "野戸まひる", 0, 0, 0, 1, "目指すはビッグな\nお笑い芸人だっぺ！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("ちょ\nちょっと一杯飲んできます…！", 2, 1, 1.4, 0, "ちょっと緊張しちゃって…", 0, 1034, 1, "綾瀬 ゆかり", 0, 0, 0, 1, "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("これ以上お話しすることは…\nないです！", 2, 1, 1.5, 0, "知らない人とは話しちゃいけないので", 0, 1036, 1, "氷川 鏡華", 0, 0, 0, 1, "氷川鏡華…です");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", 2, 1, 1.4, 0, "……あ、アラーム。", 0, 1038, 1, "柏崎 栞", 0, 0, 0, 1, "柏崎…栞です。");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("野に咲く花が、\n唯一の話相手です。", 2, 1, 1.4, 0, "私、一人も友達がいなくて……", 0, 1040, 1, "双葉 碧", 0, 0, 0, 1, "ふ、双葉碧です。");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("そう思っています。", 2, 1, 1.4, 0, "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", 0, 1042, 1, "三角 千歌", 0, 0, 0, 1, "三角千歌です。");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("う、疑ってすまなかったな…", 2, 1, 1.4, 0, "あぁ？\nお前のそいつの仲間か？", 0, 1043, 1, "安芸 真琴", 0, 0, 0, 1, "安芸真琴だ。");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", 2, 1, 1.4, 0, "生けとし生ける全ての者よ！", 0, 1044, 1, "イリヤ・オーンスタイン", 0, 0, 0, 1, "わらわこそは夜を総べる者！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("ｌク、クウカに何かご用ですか!?", 2, 1, 1.4, 0, "ぐふふふふ……はっ！", 0, 1045, 1, "遠見 空花", 0, 0, 0, 1, "そこで騎士は妖精を乱暴に……");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("う～ん…\n猫ってホントに最高にゃ～♪", 2, 1, 1.4, 0, "自由気ままで♪\n寝て遊んで、食べてケンカして…", 0, 1046, 1, "宮坂たまき", 0, 0, 0, 1, "宮坂たまきにゃ♪\n猫はいいにゃよ？");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("…と思ったら\nバイトの時間だ！\nまたあとでね！", 2, 1, 1.4, 0, "それでは早速クエストに…", 0, 1048, 1, "大神 美冬", 0, 0, 0, 1, "大神美冬よ！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("お姉ちゃんがぜ～んぶ\nやってあげるからね！", 2, 1, 1.4, 0, "クエストもバトルも\n掃除も洗濯も", 0, 1049, 1, "星野静流", 0, 0, 0, 1, "星野静流だよ！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", 2, 1, 1.5, 0, "見ての通りの\nセクシー美少女で", 0, 1050, 1, "玉泉美咲", 0, 0, 0, 1, "アタシは玉泉美咲。");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("？？？？", 2, 1, 1.4, 0, "？？？？", 0, 1052, 1, "リマ", 0, 0, 0, 1, "？？？");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("そ、そこまでいうなら\nもらってやる", 2, 1, 1.5, 0, "菓子でつろうなどと\n稚拙な策を……", 0, 1053, 1, "モニカ・ヴァイスヴィント", 0, 0, 0, 1, "モニカ・ヴァイスヴィントだ。");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("そ、そこまでいうなら\nもらってやる", 2, 1, 1.5, 0, "菓子でつろうなどと\n稚拙な策を……", 0, 1058, 1, "ペコリーヌ", 0, 0, 0, 1, "モニカ・ヴァイスヴィントだ。");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("そ、そこまでいうなら\nもらってやる", 2, 1, 1.5, 0, "菓子でつろうなどと\n稚拙な策を……", 0, 1059, 1, "コッコロ", 0, 0, 0, 1, "モニカ・ヴァイスヴィントだ。");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES ("そ、そこまでいうなら\nもらってやる", 2, 1, 1.5, 0, "菓子でつろうなどと\n稚拙な策を……", 0, 1060, 1, "キャル", 0, 0, 0, 1, "モニカ・ヴァイスヴィントだ。");
